VIP_PRICES = [  # (days, price in cents)
    (7, 499),
    (30, 1499),
    (90, 3499),
]


def add_vip_prices(apps, schema_editor):
    Product = apps.get_model("core", "Product")
    SiteSettings = apps.get_model("core", "SiteSettings")
    site = SiteSettings.objects.first()
    currency = site.currency if site else "USD"
    names = {7: "1 week", 30: "1 month", 90: "3 months"}
    for i, (days, price) in enumerate(VIP_PRICES):
        Product.objects.get_or_create(
            code=f"vip-member-{days}d",
            defaults={"kind": "membership", "name": f"VIP membership – {names[days]}", "days": days, "price": price,
                      "currency": currency, "sort_order": i, "tier": "free",
                      "description": "Message advertisers, comment, write reviews and watch videos"},
        )


def remove_vip_prices(apps, schema_editor):
    apps.get_model("core", "Product").objects.filter(kind="membership").delete()


